import {esc,stamp} from './charts.js';
export function validBars(bars){return (bars||[]).filter(b=>Number.isFinite(b.time)&&['open','high','low','close'].every(k=>Number.isFinite(b[k])&&b[k]>0)&&b.high>=Math.max(b.open,b.close,b.low)&&b.low<=Math.min(b.open,b.close,b.high)).sort((a,b)=>a.time-b.time);}
export function candleHTML(input,{currency='USD',symbol='',count=100,offset=0}={}){
 const all=validBars(input),bars=all.slice(Math.max(0,all.length-offset-count),Math.max(0,all.length-offset));
 if(!bars.length)return '<div class="candle-empty"><span>⌁</span><h3>No price history available</h3><p>Select an instrument to request its historical candles from IBKR.</p></div>';
 const low=Math.min(...bars.map(b=>b.low)),high=Math.max(...bars.map(b=>b.high)),pad=Math.max((high-low)*.08,high*.001),floor=low-pad,ceiling=high+pad;
 const x=i=>20+(i+.5)*840/bars.length,y=v=>290-(v-floor)/(ceiling-floor)*260,width=Math.max(1,Math.min(14,840/bars.length*.7)),maxVol=Math.max(1,...bars.map(b=>b.volume||0));
 const grid=Array.from({length:5},(_,i)=>{const v=ceiling-i*(ceiling-floor)/4;return `<path d="M20 ${y(v)}H860" class="gridline"/><text x="872" y="${y(v)+4}" class="axis">${v.toFixed(2)}</text>`}).join('');
 const candles=bars.map((b,i)=>{const c=b.close>=b.open?'#61dbba':'#ef7185';return `<g><line x1="${x(i)}" x2="${x(i)}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${c}"/><rect x="${x(i)-width/2}" y="${Math.min(y(b.open),y(b.close))}" width="${width}" height="${Math.max(1,Math.abs(y(b.close)-y(b.open)))}" fill="${c}"/>${Number.isFinite(b.volume)?`<rect x="${x(i)-width/2}" y="${350-b.volume/maxVol*35}" width="${width}" height="${b.volume/maxVol*35}" fill="${c}" opacity=".35"/>`:''}</g>`}).join('');
 return `<div class="candles" data-candles><div class="candle-readout">${esc(symbol)} · ${esc(currency)} · ${stamp(bars.at(-1).time)} · Close ${bars.at(-1).close.toFixed(2)}</div><svg viewBox="0 0 950 380" role="img" aria-label="${esc(symbol)} OHLC candlestick chart in ${esc(currency)}">${grid}${candles}<line data-cross x1="20" x2="20" y1="20" y2="350" stroke="#81918b" stroke-dasharray="3 4" visibility="hidden"/><text x="20" y="375" class="axis">${stamp(bars[0].time)}</text><text x="860" y="375" text-anchor="end" class="axis">${stamp(bars.at(-1).time)}</text></svg><input class="candle-scrubber" type="range" min="0" max="${bars.length-1}" value="${bars.length-1}" aria-label="Inspect candle open high low close"><div class="candle-hint">Hover or drag to inspect · Volume below · Trading sessions shown consecutively</div></div>`;
}
export function bindCandles(root,input,{count=100,offset=0,currency='USD'}={}){
 const el=root.querySelector('[data-candles]');if(!el)return;const all=validBars(input),bars=all.slice(Math.max(0,all.length-offset-count),Math.max(0,all.length-offset));const svg=el.querySelector('svg'),slider=el.querySelector('input');
 const inspect=i=>{const b=bars[i];if(!b)return;slider.value=i;const text=`${stamp(b.time)} · O ${b.open.toFixed(2)}  H ${b.high.toFixed(2)}  L ${b.low.toFixed(2)}  C ${b.close.toFixed(2)} ${currency} · Vol ${Number.isFinite(b.volume)?b.volume.toLocaleString():'—'}`;el.querySelector('.candle-readout').textContent=text;slider.setAttribute('aria-valuetext',text);const line=el.querySelector('[data-cross]'),x=20+(i+.5)*840/bars.length;line.setAttribute('x1',x);line.setAttribute('x2',x);line.setAttribute('visibility','visible');};
 slider.oninput=()=>inspect(Number(slider.value));svg.onpointermove=e=>{const box=svg.getBoundingClientRect();inspect(Math.max(0,Math.min(bars.length-1,Math.floor(((e.clientX-box.left)/box.width*950-20)/840*bars.length))));};
}
